<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="用户"><el-input v-model="query.keyword" clearable placeholder="邮箱、手机号或用户名" @keyup.enter="load"/></el-form-item><el-button type="primary" @click="load">搜索</el-button></el-form><el-table v-loading="loading" :data="rows" class="mt16"><el-table-column prop="userId" label="用户ID" width="90"/><el-table-column prop="userName" label="用户名"/><el-table-column prop="nickName" label="昵称"/><el-table-column prop="email" label="邮箱"/><el-table-column prop="phonenumber" label="手机号"/><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="s.row.status === '0' ? 'success' : 'danger'">{{ s.row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column prop="createTime" label="注册时间"/><el-table-column label="操作" width="240" fixed="right"><template #default="s"><el-button link type="primary" @click="showDetail(s.row)">详情</el-button><el-button link :type="s.row.status === '0' ? 'warning' : 'success'" @click="toggleStatus(s.row)">{{ s.row.status === '0' ? '禁用' : '启用' }}</el-button><el-button link type="danger" @click="removeUser(s.row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="detailOpen" title="用户详情" width="900px"><el-descriptions :column="3" border><el-descriptions-item label="用户名">{{ current.userName }}</el-descriptions-item><el-descriptions-item label="邮箱">{{ current.email }}</el-descriptions-item><el-descriptions-item label="手机号">{{ current.phonenumber }}</el-descriptions-item></el-descriptions><el-tabs class="detail-tabs"><el-tab-pane label="算力记录"><el-table :data="detail.creditRecords"><el-table-column prop="title" label="记录"/><el-table-column prop="recordType" label="类型"/><el-table-column prop="amount" label="算力"/><el-table-column prop="createTime" label="时间"/></el-table></el-tab-pane><el-tab-pane label="生成记录"><el-table :data="detail.tasks"><el-table-column prop="taskId" label="任务ID"/><el-table-column prop="taskType" label="类型"/><el-table-column prop="status" label="状态"/><el-table-column prop="creditCost" label="消耗"/><el-table-column prop="createTime" label="时间"/></el-table></el-tab-pane></el-tabs></el-dialog></div></template>
<script setup name="VizoraWebUser">
import { listUser, changeUserStatus, delUser } from '@/api/system/user'
import { getWebUserDetail } from '@/api/vizora/operation'
const { proxy }=getCurrentInstance(), rows=ref([]), loading=ref(false), detailOpen=ref(false), current=ref({}), detail=ref({creditRecords:[],tasks:[]}), query=reactive({keyword:undefined})
async function load(){loading.value=true;try{const res=await listUser({userName:query.keyword,phonenumber:query.keyword,email:query.keyword});rows.value=res.rows||[]}finally{loading.value=false}}
async function showDetail(row){current.value=row;const res=await getWebUserDetail(row.userId);detail.value=res.data||{creditRecords:[],tasks:[]};detailOpen.value=true}
async function toggleStatus(row){await changeUserStatus(row.userId,row.status==='0'?'1':'0');proxy.$modal.msgSuccess('状态已更新');load()}
async function removeUser(row){await proxy.$modal.confirm(`确认删除用户 ${row.userName} 吗？`);await delUser(row.userId);proxy.$modal.msgSuccess('删除成功');load()}
load()
</script>
<style scoped>.detail-tabs{margin-top:20px}.mt16{margin-top:16px}</style>
